/// Convert dialoguer errors to BivvyError.
///
/// Maps `UnexpectedEof` (triggered by Ctrl+D) to `UserCancelled`
/// so callers can handle cancellation gracefully.
fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
    if let dialoguer::Error::IO(ref io_err) = e {
        if io_err.kind() == ErrorKind::UnexpectedEof {
            return BivvyError::UserCancelled;
        }
    }
    BivvyError::Io(e.into())
}

/// Map an IO error to BivvyError, converting EOF to UserCancelled.
fn map_io_eof(e: std::io::Error) -> BivvyError {
    if e.kind() == ErrorKind::UnexpectedEof {
        BivvyError::UserCancelled
    } else {
        BivvyError::Io(e)
    }
}

